        <div className="flex flex-wrap items-center gap-1.5 max-w-[70%]">
          <button 
            onClick={handleShare}
            className="bg-white border border-[#5D4037]/20 shadow-sm px-3 py-1.5 flex items-center gap-2 hover:bg-gray-50 active:translate-y-0.5 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
            <span className="urdu-text text-sm leading-none text-[#5D4037]">شیئر کریں</span>
          </button>

          <button 
            onClick={handleCopy}
            className="bg-white border border-[#5D4037]/20 shadow-sm px-3 py-1.5 flex items-center gap-2 hover:bg-gray-50 active:translate-y-0.5 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
            <span className="urdu-text text-sm leading-none text-[#5D4037]">نقل کریں</span>
          </button>

          <button 
            onClick={() => setShowCalligraphy(!showCalligraphy)}
            className={`bg-white border border-[#5D4037]/20 shadow-sm px-4 py-1.5 urdu-text text-sm leading-none text-[#5D4037] hover:bg-gray-50 transition-all ${showCalligraphy ? 'ring-1 ring-[#5D4037]' : ''}`}
          >
            نقش و نگار
          </button>

          <button 
            onClick={() => setShowLineNumbers(!showLineNumbers)}
            className={`bg-white border border-[#5D4037]/20 shadow-sm px-4 py-1.5 urdu-text text-sm leading-none text-[#5D4037] hover:bg-gray-50 transition-all ${showLineNumbers ? 'ring-1 ring-[#5D4037]' : ''}`}
          >
