export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [showCalligraphy, setShowCalligraphy] = useState(false);
  const [showLineNumbers, setShowLineNumbers] = useState(false);
  const [copied, setCopied] = useState(false);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try {
        await navigator.share({ title: lyric.title, text: textToShare });
      } catch (err) { handleCopy(); }
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  return (
    <div className="flex flex-col items-center w-full h-full text-center relative min-h-[70vh]">
      {/* 
        Professional Toolbar Section 
        Responsive, properly aligned, matching user screenshot 
      */}
      <div className="w-full relative z-40 flex flex-row items-center justify-between mb-12 gap-2 px-1 py-2" dir="ltr">
        {/* Action Group (Left-aligned) */}
        <div className="flex flex-wrap items-center gap-1">
          <button 
            onClick={handleShare}
            className="bg-white border border-gray-200 shadow-sm px-2.5 py-1.5 flex items-center gap-2 hover:bg-gray-50 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
            <span className="urdu-text text-sm leading-none text-[#5D4037]">شیئر کریں</span>
          </button>

          <button 
            onClick={handleCopy}
            className="bg-white border border-gray-200 shadow-sm px-2.5 py-1.5 flex items-center gap-2 hover:bg-gray-50 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
            <span className="urdu-text text-sm leading-none text-[#5D4037]">{copied ? 'نقل ہو گیا' : 'نقل کریں'}</span>
          </button>

          <button 
            onClick={() => setShowCalligraphy(!showCalligraphy)}
            className={`bg-white border border-gray-200 shadow-sm px-3 py-1.5 urdu-text text-sm leading-none text-[#5D4037] hover:bg-gray-50 transition-all ${showCalligraphy ? 'ring-1 ring-[#5D4037]' : ''}`}
          >
            نقش و نگار
          </button>

          <button 
            onClick={() => setShowLineNumbers(!showLineNumbers)}
            className={`bg-white border border-gray-200 shadow-sm px-3 py-1.5 urdu-text text-sm leading-none text-[#5D4037] hover:bg-gray-50 transition-all ${showLineNumbers ? 'ring-1 ring-[#5D4037]' : ''}`}
          >
            شمار نمبر
          </button>
        </div>

        {/* Back Button (Pill style on Right) */}
        <button 
          onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)}
          className="bg-white border border-gray-200 shadow-md rounded-full px-5 py-2 flex items-center gap-2 text-[#5D4037] font-bold text-xs transition-all hover:bg-gray-50 active:scale-95 shrink-0"
        >
          <span className="font-sans">BACK</span>
          <svg className="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 18l-6-6 6-6"/>
          </svg>
        </button>
      </div>

      {/* Background Decor */}
      {showCalligraphy && <CalligraphyWatermark color={displaySettings.textColor} />}

      {/* Main Content Area */}
      <div className="relative z-10 w-full flex-grow flex flex-col items-center">
        {/* Title: Clean typography, no background bar as requested */}
        <div className="w-full mb-16 flex flex-col items-center">
           <h3 className="text-2xl md:text-3xl font-bold urdu-text leading-tight text-[#5D4037] px-6">
            {lyric.title}
          </h3>
          <div className="w-16 h-0.5 bg-[#5D4037] mt-3 opacity-20"></div>
        </div>

        <div 
          className="flex flex-col items-center w-full urdu-text font-medium px-4 whitespace-pre-wrap"
          style={{ 
            color: displaySettings.textColor,
            fontSize: `${displaySettings.fontSize}px`,
            lineHeight: displaySettings.lineHeight
          }}
        >
          {lyric.content.split('\n').map((line, i) => (
             <React.Fragment key={i}>
               <div className="w-full flex items-center justify-center group relative py-1">
                 {showLineNumbers && (
                   <span 
                    className="absolute -right-6 top-1 text-[10px] font-bold font-sans opacity-40 group-hover:opacity-100 transition-opacity"
                    style={{ color: displaySettings.textColor }}
                   >
                     {(i + 1).toString().padStart(2, '0')}
                   </span>
                 )}
                 <div className="flex-grow text-center px-2">
                   {line}
                 </div>
               </div>
               {i < lyric.content.split('\n').length - 1 && <LineDivider color={displaySettings.textColor} />}
             </React.Fragment>
          ))}
        </div>
      </div>

      {/* Sequential Navigation Controls - Redesigned as clean white cards */}
      <div className="w-full grid grid-cols-2 gap-4 mt-20 mb-12 relative z-20" dir="rtl">
        <button
          disabled={!nextLyric}
          onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
          className={`urdu-text py-3 border border-gray-200 text-[#5D4037] font-bold text-lg transition-all active:scale-95 flex items-center justify-center gap-3 bg-white shadow-sm ${!nextLyric ? 'opacity-20 cursor-not-allowed' : 'hover:border-[#5D4037]/40'}`}
        >
          اگلا کلام
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7"/></svg>
        </button>
        <button
          disabled={!prevLyric}
          onClick={() => prevLyric && navigate(`/lyric/${prevLyric.id}`)}
          className={`urdu-text py-3 border border-gray-200 text-[#5D4037] font-bold text-lg transition-all active:scale-95 flex items-center justify-center gap-3 bg-white shadow-sm ${!prevLyric ? 'opacity-20 cursor-not-allowed' : 'hover:border-[#5D4037]/40'}`}
        >
           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24" strokeWidth="2.5"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg>
          پچھلا کلام
        </button>
      </div>
    </div>
  );
};

