    <div className="h-[0.5px] w-12" style={{ backgroundColor: color }}></div>
  </div>
);

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [showCalligraphy, setShowCalligraphy] = useState(false);
  const [showLineNumbers, setShowLineNumbers] = useState(false);
  const [copied, setCopied] = useState(false);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); } catch (err) {}
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  return (
    <div className="flex flex-col items-center w-full h-full text-center relative">
      {/* 
        Professional Toolbar - Redesigned to be clean and responsive
        Left: Share Icon, Copy Icon, Design Toggle, Serial Toggle
        Right: BACK Pill
      */}
      <div className="w-full relative z-40 flex flex-row items-center justify-between mb-10 pt-2 pb-4 border-b border-[#5D4037]/5" dir="ltr">
        <div className="flex flex-wrap items-center gap-1.5 flex-1 pr-2">
          {/* Share Icon Only */}
          <button 
            onClick={handleShare}
            title="Share"
            className="bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:translate-y-0.5 transition-all"
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
          </button>

          {/* Copy Icon Only */}
          <button 
            onClick={handleCopy}
            title="Copy"
            className={`bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:translate-y-0.5 transition-all ${copied ? 'bg-green-50' : ''}`}
          >
            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
          </button>

          {/* Text Buttons for Design/Serial */}
          <button 
            onClick={() => setShowCalligraphy(!showCalligraphy)}
            className={`bg-white border border-[#5D4037]/15 shadow-sm px-3 py-1.5 urdu-text text-sm leading-none text-[#5D4037] hover:bg-gray-50 transition-all ${showCalligraphy ? 'bg-[#5D4037] text-white' : ''}`}
          >
            نقش و نگار
          </button>

          <button 
            onClick={() => setShowLineNumbers(!showLineNumbers)}
            className={`bg-white border border-[#5D4037]/15 shadow-sm px-3 py-1.5 urdu-text text-sm leading-none text-[#5D4037] hover:bg-gray-50 transition-all ${showLineNumbers ? 'bg-[#5D4037] text-white' : ''}`}
          >
            شمار نمبر
          </button>
        </div>

        {/* Back Pill Button */}
        <button 
          onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)}
          className="bg-white border border-[#5D4037]/10 shadow-lg rounded-full px-5 py-2.5 flex items-center gap-3 text-[#5D4037] font-bold text-xs tracking-widest transition-all hover:bg-gray-50 active:scale-95 shrink-0"
        >
