          className={`bg-white border border-[#5D4037]/10 py-3 shadow-md transition-all active:scale-95 flex items-center justify-center gap-3 rounded-sm ${!prevLyric ? 'opacity-10 grayscale cursor-not-allowed' : 'hover:border-[#5D4037]/30'}`}
        >
          <svg className="w-4 h-4" fill="none" stroke="#5D4037" viewBox="0 0 24 24" strokeWidth="4"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg>
          <span className="font-sans text-xs font-bold tracking-widest text-[#5D4037]">BACK</span>
        </button>
        <button
          disabled={!nextLyric}
          onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
          className={`bg-white border border-[#5D4037]/10 py-3 shadow-md transition-all active:scale-95 flex items-center justify-center gap-3 rounded-sm ${!nextLyric ? 'opacity-10 grayscale cursor-not-allowed' : 'hover:border-[#5D4037]/30'}`}
        >
          <span className="font-sans text-xs font-bold tracking-widest text-[#5D4037]">NEXT</span>
          <svg className="w-4 h-4" fill="none" stroke="#5D4037" viewBox="0 0 24 24" strokeWidth="4"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7"/></svg>
        </button>
      </div>
    </div>
  );
};

