import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../db';
import { Lyric, DisplaySettings } from '../types';

const CalligraphyWatermark: React.FC<{ color: string }> = ({ color }) => (
  <div className="absolute inset-0 flex items-center justify-center pointer-events-none opacity-[0.03] overflow-hidden z-0 animate-fadeIn">
    <svg width="400" height="400" viewBox="0 0 400 400" fill="none" stroke={color} strokeWidth="0.5">
      <circle r="90" cx="200" cy="200" strokeWidth="0.4" strokeDasharray="5 5" />
      <text x="200" y="212" textAnchor="middle" fontSize="48" className="urdu-text" fill={color} stroke="none" opacity="0.7">
        محمد ﷺ
      </text>
    </svg>
  </div>
);

const LineDivider: React.FC<{ color: string }> = ({ color }) => (
  <div className="flex items-center justify-center w-full my-4 opacity-[0.1] select-none pointer-events-none">
    <div className="h-[0.5px] w-8" style={{ backgroundColor: color }}></div>
    <div className="mx-2 rotate-45 border w-1 h-1" style={{ borderColor: color }}></div>
    <div className="h-[0.5px] w-8" style={{ backgroundColor: color }}></div>
  </div>
);

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [copied, setCopied] = useState(false);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());

  // Audio State
  const [isPlaying, setIsPlaying] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Swipe State
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const minSwipeDistance = 50;

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  // Audio Handler
  useEffect(() => {
    if (lyric?.audioUrl) {
      audioRef.current = new Audio(lyric.audioUrl);
      audioRef.current.onended = () => setIsPlaying(false);
    } else {
      audioRef.current = null;
    }
    return () => {
      audioRef.current?.pause();
      setIsPlaying(false);
    };
  }, [id, lyric?.audioUrl]);

  const toggleAudio = () => {
    if (!audioRef.current) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  // Swipe Handlers
  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;
    if (isLeftSwipe && nextLyric) navigate(`/lyric/${nextLyric.id}`);
    if (isRightSwipe && prevLyric) navigate(`/lyric/${prevLyric.id}`);
  };

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); } catch (err) {}
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  return (
    <div 
      className="flex flex-col items-center w-full h-full text-center relative px-10 py-10 min-h-[85vh] touch-none"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <style>{`
        @keyframes titleSlideUp {
          from { opacity: 0; transform: translateY(15px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-title {
          animation: titleSlideUp 0.8s cubic-bezier(0.2, 0.8, 0.2, 1) both;
        }
      `}</style>

      {/* Top Toolbar */}
      <div className="w-full relative z-40 flex flex-row items-center justify-between mb-8" dir="ltr">
        <div className="flex items-center gap-2">
          <button onClick={handleShare} className="bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:scale-95 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
          </button>
          <button onClick={handleCopy} className={`bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:scale-95 transition-all ${copied ? 'bg-green-50' : ''}`}>
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
          </button>
        </div>
        <button onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)} className="bg-white border border-[#5D4037]/10 shadow-md rounded-full w-10 h-10 flex items-center justify-center text-[#5D4037] transition-all hover:bg-gray-50 active:scale-90">
          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 18l-6-6 6-6"/>
          </svg>
        </button>
      </div>

      <CalligraphyWatermark color={displaySettings.textColor} />

      {/* Main Content Area */}
      <div className="relative z-10 w-full flex-grow flex flex-col items-center">
        <div className="w-full mb-10 flex flex-col items-center animate-title">
          <div className="flex items-center justify-center gap-3">
            {lyric.audioUrl && (
              <button 
                onClick={toggleAudio}
                className="w-10 h-10 rounded-full bg-[#5D4037]/5 border border-[#5D4037]/10 flex items-center justify-center text-[#5D4037] active:scale-90 transition-all hover:bg-[#5D4037]/10"
              >
                {isPlaying ? (
                  <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>
                ) : (
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                )}
              </button>
            )}
            <h3 className="text-2xl font-bold urdu-text leading-snug text-[#5D4037]">
              {lyric.title}
            </h3>
          </div>
          <div className="w-12 h-[0.5px] bg-[#5D4037] mt-2 opacity-10"></div>
        </div>

        <div 
          className="flex flex-col items-center w-full urdu-text font-medium whitespace-pre-wrap"
          style={{ 
            color: displaySettings.textColor,
            fontSize: `${displaySettings.fontSize}px`,
            lineHeight: displaySettings.lineHeight
          }}
        >
          {lyric.content.split('\n').map((line, i) => (
             <React.Fragment key={i}>
               <div className="w-full text-center py-1">
                 {line}
               </div>
               {i < lyric.content.split('\n').length - 1 && <LineDivider color={displaySettings.textColor} />}
             </React.Fragment>
          ))}
        </div>
      </div>

      {/* Bottom Nav */}
      <div className="w-full flex flex-row items-center justify-center gap-4 mt-16 mb-2 relative z-20" dir="ltr">
        <button
          disabled={!prevLyric}
          onClick={() => prevLyric && navigate(`/lyric/${prevLyric.id}`)}
          className={`flex-1 bg-white border border-[#5D4037]/10 py-2.5 shadow-md flex items-center justify-center gap-2 transition-all active:scale-95 ${!prevLyric ? 'opacity-20 grayscale' : 'hover:bg-gray-50'}`}
        >
          <svg className="w-3 h-3" fill="none" stroke="#5D4037" viewBox="0 0 24 24" strokeWidth="4"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg>
          <span className="font-sans text-[10px] font-bold tracking-widest text-[#5D4037]">BACK</span>
        </button>

        <button
          disabled={!nextLyric}
          onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
          className={`flex-1 bg-white border border-[#5D4037]/10 py-2.5 shadow-md flex items-center justify-center gap-2 transition-all active:scale-95 ${!nextLyric ? 'opacity-20 grayscale' : 'hover:bg-gray-50'}`}
        >
          <span className="font-sans text-[10px] font-bold tracking-widest text-[#5D4037]">NEXT</span>
          <svg className="w-3 h-3" fill="none" stroke="#5D4037" viewBox="0 0 24 24" strokeWidth="4"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7"/></svg>
        </button>
      </div>
    </div>
  );
};

