                {/* Play/Pause Button Inner */}
                <div className="w-9 h-9 rounded-full bg-[#5D4037]/10 border border-[#5D4037]/20 flex items-center justify-center text-[#5D4037] active:scale-90 transition-all hover:bg-[#5D4037]/20 shadow-sm relative z-10">
