        </div>
        <button onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)} className="bg-white border border-[#5D4037]/10 shadow-md rounded-full w-10 h-10 flex items-center justify-center text-[#5D4037] transition-all hover:bg-gray-50 active:scale-90">
          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 18l-6-6 6-6"/>
          </svg>
        </button>
      </div>

      <CalligraphyWatermark color={displaySettings.textColor} />

      {/* Main Content Area */}
      <div className="relative z-10 w-full flex-grow flex flex-col items-center overflow-y-auto max-h-[60vh] custom-scrollbar px-2">
        <div className="w-full mb-10 flex flex-col items-center animate-title">
          <FastQuranLogoSmall />

          <div className="flex flex-col items-center gap-2">
            <div className="flex items-center justify-center gap-4">
              {lyric.audioUrl && (
                <button 
                  onClick={toggleAudio}
                  className={`relative w-14 h-14 flex items-center justify-center group shrink-0 ${isPlaying ? 'playing-pulse' : ''}`}
                  title={isPlaying ? "Pause" : "Play recitation"}
                >
                  {/* Circular Progress Indicator SVG */}
                  <svg 
                    className={`absolute inset-0 w-full h-full -rotate-90 transform ${isBuffering ? 'animate-spin-custom' : ''}`} 
                    viewBox="0 0 40 40"
                  >
                    <circle
                      className="text-[#5D4037]/10"
                      strokeWidth="2.5"
                      stroke="currentColor"
                      fill="transparent"
                      r={radius}
                      cx="20"
                      cy="20"
                    />
                    <circle
                      className="text-[#5D4037] transition-all duration-300"
                      strokeWidth="2.5"
                      strokeDasharray={circumference}
                      strokeDashoffset={isBuffering ? circumference * 0.7 : strokeDashoffset}
                      strokeLinecap="round"
                      stroke="currentColor"
                      fill="transparent"
                      r={radius}
                      cx="20"
                      cy="20"
                    />
                  </svg>

                  {/* Play/Pause Button Inner */}
                  <div className="w-10 h-10 rounded-full bg-[#5D4037]/10 border border-[#5D4037]/20 flex items-center justify-center text-[#5D4037] active:scale-90 transition-all hover:bg-[#5D4037]/20 shadow-sm relative z-10">
                    {isBuffering ? (
                      <div className="w-4 h-4 border-2 border-[#5D4037]/30 border-t-[#5D4037] rounded-full animate-spin"></div>
                    ) : isPlaying ? (
                      <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>
                    ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                    )}
                  </div>
                </button>
              )}
              <h3 className="text-3xl font-bold urdu-text leading-snug text-[#5D4037] drop-shadow-sm">
                {lyric.title}
              </h3>
            </div>

            {/* Playback Time Display */}
            {lyric.audioUrl && (isPlaying || currentTime > 0) && (
              <div className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#5D4037]/5 border border-[#5D4037]/5 font-sans text-[10px] font-bold tracking-tighter text-[#5D4037]/60 animate-fadeIn">
                <span className="text-[#5D4037]">{formatTime(currentTime)}</span>
                <span className="opacity-30">/</span>
                <span>{formatTime(duration)}</span>
              </div>
            )}
          </div>
          <div className="w-16 h-[0.5px] bg-[#5D4037] mt-3 opacity-10"></div>
        </div>

        <div 
          className="flex flex-col items-center w-full urdu-text font-medium whitespace-pre-wrap"
          style={{ 
            color: displaySettings.textColor,
            fontSize: `${displaySettings.fontSize}px`,
            lineHeight: displaySettings.lineHeight
          }}
        >
          {lyric.content.split('\n').map((line, i) => (
             <React.Fragment key={i}>
               <div className="w-full text-center py-2 px-1">
                 {line}
               </div>
               {i < lyric.content.split('\n').length - 1 && line.trim() !== '' && <LineDivider color={displaySettings.textColor} />}
             </React.Fragment>
          ))}
        </div>
      </div>

      {/* Bottom Nav */}
      <div className="w-full flex flex-row items-center justify-center gap-4 mt-12 mb-2 relative z-20" dir="ltr">
        <button
          disabled={!prevLyric}
          onClick={() => prevLyric && navigate(`/lyric/${prevLyric.id}`)}
          className={`flex-1 bg-white border border-[#5D4037]/10 py-3 shadow-md flex items-center justify-center gap-2 transition-all active:scale-95 ${!prevLyric ? 'opacity-20 grayscale' : 'hover:bg-gray-50'}`}
        >
          <svg className="w-3.5 h-3.5" fill="none" stroke="#5D4037" viewBox="0 0 24 24" strokeWidth="4"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7"/></svg>
          <span className="font-sans text-[11px] font-bold tracking-widest text-[#5D4037]">BACK</span>
        </button>

        <button
          disabled={!nextLyric}
          onClick={() => nextLyric && navigate(`/lyric/${nextLyric.id}`)}
          className={`flex-1 bg-white border border-[#5D4037]/10 py-3 shadow-md flex items-center justify-center gap-2 transition-all active:scale-95 ${!nextLyric ? 'opacity-20 grayscale' : 'hover:bg-gray-50'}`}
        >
          <span className="font-sans text-[11px] font-bold tracking-widest text-[#5D4037]">NEXT</span>
          <svg className="w-3.5 h-3.5" fill="none" stroke="#5D4037" viewBox="0 0 24 24" strokeWidth="4"><path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7"/></svg>
        </button>
      </div>
    </div>
  );
};

