export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [copied, setCopied] = useState(false);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());

  // Audio State
  const [isPlaying, setIsPlaying] = useState(false);
  const [isBuffering, setIsBuffering] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  // References for playback
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const startTimeRef = useRef<number>(0);
  const progressIntervalRef = useRef<number | null>(null);

  // Swipe State
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const minSwipeDistance = 50;

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const formatTime = (time: number) => {
    if (isNaN(time)) return '00:00';
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const handleAudioEnd = () => {
    setIsPlaying(false);
    setProgress(0);
    setCurrentTime(0);
    if (nextLyric) {
      navigate(`/lyric/${nextLyric.id}`);
    }
  };

  // Static Audio Handler (for pre-recorded recitations)
  useEffect(() => {
    if (lyric?.audioUrl && !isPlaying) {
      const audio = new Audio(lyric.audioUrl);
      audioRef.current = audio;

      const updateProgress = () => {
        setCurrentTime(audio.currentTime);
        if (audio.duration) {
          setDuration(audio.duration);
          setProgress((audio.currentTime / audio.duration) * 100);
        }
      };

      const handleWaiting = () => setIsBuffering(true);
      const handlePlaying = () => setIsBuffering(false);
      const handleLoaded = () => {
        setIsBuffering(false);
        setDuration(audio.duration);
      };

      audio.addEventListener('timeupdate', updateProgress);
      audio.addEventListener('waiting', handleWaiting);
      audio.addEventListener('playing', handlePlaying);
      audio.addEventListener('canplay', handleLoaded);
      audio.addEventListener('loadedmetadata', handleLoaded);
      audio.addEventListener('ended', handleAudioEnd);

      return () => {
        audio.removeEventListener('timeupdate', updateProgress);
        audio.removeEventListener('waiting', handleWaiting);
        audio.removeEventListener('playing', handlePlaying);
        audio.removeEventListener('canplay', handleLoaded);
        audio.removeEventListener('loadedmetadata', handleLoaded);
        audio.removeEventListener('ended', handleAudioEnd);
        audio.pause();
      };
    }
  }, [id, lyric?.audioUrl]);

  // Clean up Web Audio on unmount or id change
  useEffect(() => {
    return () => {
      stopTtsPlayback();
    };
  }, [id]);

  const stopTtsPlayback = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch(e) {}
      sourceNodeRef.current = null;
    }
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
    setIsPlaying(false);
  };

  const playTtsAudio = async (base64Data: string) => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
    }
    const ctx = audioContextRef.current;
    if (ctx.state === 'suspended') await ctx.resume();

    const audioBuffer = await decodeAudioData(decodeBase64(base64Data), ctx, 24000, 1);

    stopTtsPlayback();

    const source = ctx.createBufferSource();
    source.buffer = audioBuffer;
    source.connect(ctx.destination);

    source.onended = handleAudioEnd;

    setDuration(audioBuffer.duration);
    startTimeRef.current = ctx.currentTime;
    source.start(0);
    sourceNodeRef.current = source;
    setIsPlaying(true);

    progressIntervalRef.current = window.setInterval(() => {
      const elapsed = ctx.currentTime - startTimeRef.current;
      setCurrentTime(elapsed);
      setProgress((elapsed / audioBuffer.duration) * 100);
    }, 100);
  };

  const toggleAudio = async () => {
    // If we have a source node (TTS), stop it
    if (sourceNodeRef.current) {
      stopTtsPlayback();
      return;
    }

    // If we have HTML audio, toggle it
    if (audioRef.current && lyric?.audioUrl) {
      if (isPlaying) {
        audioRef.current.pause();
        setIsPlaying(false);
      } else {
        audioRef.current.play().catch(e => console.error("Audio play failed:", e));
        setIsPlaying(true);
      }
      return;
    }

    // Otherwise, generate TTS
    if (lyric?.content) {
      setIsBuffering(true);
      try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const prompt = `Recite this Urdu poetry with a soulful, clear, and emotional voice. Please speak slowly and naturally:\n\n${lyric.content}`;
        const response = await ai.models.generateContent({
          model: 'gemini-2.5-flash-preview-tts',
          contents: [{ parts: [{ text: prompt }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: {
                prebuiltVoiceConfig: { voiceName: 'Zephyr' },
              },
            },
          },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
          await playTtsAudio(base64Audio);
        }
      } catch (error) {
        console.error("TTS generation failed:", error);
      } finally {
        setIsBuffering(false);
      }
    }
  };

  // Swipe Handlers
  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;
    if (isLeftSwipe && nextLyric) navigate(`/lyric/${nextLyric.id}`);
    if (isRightSwipe && prevLyric) navigate(`/lyric/${prevLyric.id}`);
  };

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); } catch (err) {}
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  // Constants for circular progress
  const radius = 18;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  return (
    <div 
      className="flex flex-col items-center w-full h-full text-center relative px-10 py-10 min-h-[85vh] touch-none"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <style>{`
        @keyframes titleSlideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-title {
          animation: titleSlideUp 1.2s cubic-bezier(0.16, 1, 0.3, 1) both;
        }
        @keyframes fadeInScale {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
        .copied-badge {
          animation: fadeInScale 0.2s ease-out both;
        }
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
        .animate-spin-custom {
          animation: spin 2s linear infinite;
        }
        @keyframes audioPulse {
          0% { box-shadow: 0 0 0 0 rgba(93, 64, 55, 0.2); transform: scale(1); }
          70% { box-shadow: 0 0 0 10px rgba(93, 64, 55, 0); transform: scale(1.05); }
          100% { box-shadow: 0 0 0 0 rgba(93, 64, 55, 0); transform: scale(1); }
        }
        .playing-pulse {
          animation: audioPulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
      `}</style>

      {/* Top Toolbar */}
      <div className="w-full relative z-40 flex flex-row items-center justify-between mb-8" dir="ltr">
        <div className="flex items-center gap-2">
          <button onClick={handleShare} className="bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:scale-95 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
          </button>
          <button 
            onClick={handleCopy} 
            className={`bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:scale-95 transition-all min-w-[36px] ${copied ? 'bg-green-50 border-green-200' : ''}`}
          >
