export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [copied, setCopied] = useState(false);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>(db.getSettings());

  // Audio State
  const [isPlaying, setIsPlaying] = useState(false);
  const [isBuffering, setIsBuffering] = useState(false);
  const [progress, setProgress] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  // Playback Refs
  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const staticAudioRef = useRef<HTMLAudioElement | null>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const playbackStartTimeRef = useRef<number>(0);

  // Swipe State
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const [touchEnd, setTouchEnd] = useState<number | null>(null);
  const minSwipeDistance = 50;

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  const { prevLyric, nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { prevLyric: null, nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      prevLyric: currentIndex > 0 ? subCategoryLyrics[currentIndex - 1] : null,
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const formatTime = (time: number) => {
    if (isNaN(time)) return '00:00';
    const mins = Math.floor(time / 60);
    const secs = Math.floor(time % 60);
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const cleanupAudio = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch(e) {}
      sourceNodeRef.current = null;
    }
    if (staticAudioRef.current) {
      staticAudioRef.current.pause();
      staticAudioRef.current = null;
    }
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
    setIsPlaying(false);
    setProgress(0);
    setCurrentTime(0);
  };

  const onRecitationEnd = () => {
    cleanupAudio();
    if (nextLyric) {
      navigate(`/lyric/${nextLyric.id}`);
    }
  };

  const playGeminiTts = async (text: string) => {
    setIsBuffering(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: `Please recite this Urdu poetry clearly and emotionally:\n\n${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Zephyr' }, // Expressive, helpful voice
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data returned");

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = onRecitationEnd;

      setDuration(audioBuffer.duration);
      playbackStartTimeRef.current = ctx.currentTime;
      source.start(0);
      sourceNodeRef.current = source;
      setIsPlaying(true);

      progressIntervalRef.current = window.setInterval(() => {
        const elapsed = ctx.currentTime - playbackStartTimeRef.current;
        setCurrentTime(elapsed);
        setProgress((elapsed / audioBuffer.duration) * 100);
      }, 100);

    } catch (error) {
      console.error("TTS failed:", error);
      alert("Recitation failed. Please check your connection or API key.");
    } finally {
      setIsBuffering(false);
    }
  };

  const toggleAudio = async () => {
    if (isPlaying) {
      cleanupAudio();
      return;
    }

    // Prefer pre-recorded audio if it exists in the database
    if (lyric?.audioUrl) {
      setIsBuffering(true);
      const audio = new Audio(lyric.audioUrl);
      staticAudioRef.current = audio;

      audio.oncanplay = () => {
        setIsBuffering(false);
        setDuration(audio.duration);
        audio.play();
        setIsPlaying(true);
      };

      audio.ontimeupdate = () => {
        setCurrentTime(audio.currentTime);
        setProgress((audio.currentTime / audio.duration) * 100);
      };

      audio.onended = onRecitationEnd;
      audio.onerror = () => {
        setIsBuffering(false);
        // Fallback to TTS if static URL fails
        playGeminiTts(lyric.content);
      };
    } else if (lyric?.content) {
      playGeminiTts(lyric.content);
    }
  };

  useEffect(() => {
    return () => cleanupAudio();
  }, [id]);

  // Swipe Handlers
  const onTouchStart = (e: React.TouchEvent) => {
    setTouchEnd(null);
    setTouchStart(e.targetTouches[0].clientX);
  };

  const onTouchMove = (e: React.TouchEvent) => {
    setTouchEnd(e.targetTouches[0].clientX);
  };

  const onTouchEnd = () => {
    if (!touchStart || !touchEnd) return;
    const distance = touchStart - touchEnd;
    const isLeftSwipe = distance > minSwipeDistance;
    const isRightSwipe = distance < -minSwipeDistance;
    if (isLeftSwipe && nextLyric) navigate(`/lyric/${nextLyric.id}`);
    if (isRightSwipe && prevLyric) navigate(`/lyric/${prevLyric.id}`);
  };

  const handleCopy = () => {
    if (lyric) {
      const fullContent = `${lyric.title}\n\n${lyric.content}`;
      navigator.clipboard.writeText(fullContent).then(() => {
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
      });
    }
  };

  const handleShare = async () => {
    if (!lyric) return;
    const textToShare = `${lyric.title}\n\n${lyric.content}`;
    if (navigator.share) {
      try { await navigator.share({ title: lyric.title, text: textToShare }); } catch (err) {}
    } else { handleCopy(); }
  };

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  const radius = 18;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  return (
    <div 
      className="flex flex-col items-center w-full h-full text-center relative px-10 py-10 min-h-[85vh] touch-none"
      onTouchStart={onTouchStart}
      onTouchMove={onTouchMove}
      onTouchEnd={onTouchEnd}
    >
      <style>{`
        @keyframes titleSlideUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
        .animate-title {
          animation: titleSlideUp 1.2s cubic-bezier(0.16, 1, 0.3, 1) both;
        }
        @keyframes fadeInScale {
          from { opacity: 0; transform: scale(0.9); }
          to { opacity: 1; transform: scale(1); }
        }
        .copied-badge {
          animation: fadeInScale 0.2s ease-out both;
        }
        @keyframes spin {
          to { transform: rotate(360deg); }
        }
        .animate-spin-custom {
          animation: spin 2s linear infinite;
        }
        @keyframes audioPulse {
          0% { box-shadow: 0 0 0 0 rgba(93, 64, 55, 0.2); transform: scale(1); }
          70% { box-shadow: 0 0 0 10px rgba(93, 64, 55, 0); transform: scale(1.05); }
          100% { box-shadow: 0 0 0 0 rgba(93, 64, 55, 0); transform: scale(1); }
        }
        .playing-pulse {
          animation: audioPulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
        }
      `}</style>

      {/* Top Toolbar */}
      <div className="w-full relative z-40 flex flex-row items-center justify-between mb-8" dir="ltr">
        <div className="flex items-center gap-2">
          <button onClick={handleShare} className="bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:scale-95 transition-all">
            <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
          </button>
          <button 
            onClick={handleCopy} 
            className={`bg-white border border-[#5D4037]/15 shadow-sm p-2 flex items-center justify-center hover:bg-gray-50 active:scale-95 transition-all min-w-[36px] ${copied ? 'bg-green-50 border-green-200' : ''}`}
          >
            {copied ? (
              <div className="flex items-center gap-1 copied-badge">
                <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#2E7D32" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                <span className="text-[10px] font-bold text-[#2E7D32] uppercase tracking-tighter mr-1">Copied</span>
              </div>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
            )}
          </button>
        </div>
        <button onClick={() => navigate(`/subcategory/${lyric.subCategoryId}`)} className="bg-white border border-[#5D4037]/10 shadow-md rounded-full w-10 h-10 flex items-center justify-center text-[#5D4037] transition-all hover:bg-gray-50 active:scale-90">
          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
            <path d="M15 18l-6-6 6-6"/>
          </svg>
        </button>
      </div>

      <CalligraphyWatermark color={displaySettings.textColor} />

      {/* Main Content Area */}
      <div className="relative z-10 w-full flex-grow flex flex-col items-center overflow-y-auto max-h-[60vh] custom-scrollbar px-2">
        <div className="w-full mb-10 flex flex-col items-center animate-title">
          <FastQuranLogoSmall />

          <div className="flex flex-col items-center gap-2">
            <div className="flex items-center justify-center gap-4">
              <button 
                onClick={toggleAudio}
                className={`relative w-14 h-14 flex items-center justify-center group shrink-0 ${isPlaying ? 'playing-pulse' : ''}`}
                title={isPlaying ? "Stop" : "Listen to recitation"}
                disabled={isBuffering}
              >
                {/* Circular Progress Indicator SVG */}
                <svg 
                  className={`absolute inset-0 w-full h-full -rotate-90 transform ${isBuffering ? 'animate-spin-custom' : ''}`} 
                  viewBox="0 0 40 40"
                >
                  <circle
                    className="text-[#5D4037]/10"
                    strokeWidth="2.5"
                    stroke="currentColor"
                    fill="transparent"
                    r={radius}
                    cx="20"
                    cy="20"
                  />
                  <circle
                    className="text-[#5D4037] transition-all duration-300"
                    strokeWidth="2.5"
                    strokeDasharray={circumference}
                    strokeDashoffset={isBuffering ? circumference * 0.7 : strokeDashoffset}
                    strokeLinecap="round"
                    stroke="currentColor"
                    fill="transparent"
                    r={radius}
                    cx="20"
                    cy="20"
                  />
                </svg>

                {/* Play/Stop Button Inner */}
                <div className="w-10 h-10 rounded-full bg-[#5D4037]/10 border border-[#5D4037]/20 flex items-center justify-center text-[#5D4037] active:scale-90 transition-all hover:bg-[#5D4037]/20 shadow-sm relative z-10">
                  {isBuffering ? (
                    <div className="w-4 h-4 border-2 border-[#5D4037]/30 border-t-[#5D4037] rounded-full animate-spin"></div>
                  ) : isPlaying ? (
                    <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="12" height="16" rx="1"/></svg>
                  ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
                  )}
                </div>
              </button>
              <h3 className="text-3xl font-bold urdu-text leading-snug text-[#5D4037] drop-shadow-sm">
                {lyric.title}
              </h3>
            </div>

            {/* Playback Time Display */}
            {(isPlaying || currentTime > 0) && (
              <div className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-[#5D4037]/5 border border-[#5D4037]/5 font-sans text-[10px] font-bold tracking-tighter text-[#5D4037]/60 animate-fadeIn">
                <span className="text-[#5D4037]">{formatTime(currentTime)}</span>
                <span className="opacity-30">/</span>
                <span>{formatTime(duration)}</span>
              </div>
            )}
          </div>
          <div className="w-16 h-[0.5px] bg-[#5D4037] mt-3 opacity-10"></div>
        </div>

        <div 
          className="flex flex-col items-center w-full urdu-text font-medium whitespace-pre-wrap"
          style={{ 
            color: displaySettings.textColor,
            fontSize: `${displaySettings.fontSize}px`,
            lineHeight: displaySettings.lineHeight
          }}
        >
          {lyric.content.split('\n').map((line, i) => (
             <React.Fragment key={i}>
               <div className="w-full text-center py-2 px-1">
                 {line}
