// Helper functions for base64 and audio decoding
function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [subCategoryLyrics, setSubCategoryLyrics] = useState<Lyric[]>([]);
  const [displaySettings] = useState<DisplaySettings>(db.getSettings());

  const [isPlaying, setIsPlaying] = useState(false);
  const [isBuffering, setIsBuffering] = useState(false);
  const [progress, setProgress] = useState(0);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const staticAudioRef = useRef<HTMLAudioElement | null>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const playbackStartTimeRef = useRef<number>(0);

  useEffect(() => {
    if (id) {
      const allLyrics = db.getLyrics();
      const currentLyric = allLyrics.find(l => l.id === id);
      if (currentLyric) {
        setLyric(currentLyric);
        setSubCategoryLyrics(db.getLyrics(currentLyric.subCategoryId));
      }
    }
  }, [id]);

  const { nextLyric } = useMemo(() => {
    if (!lyric || subCategoryLyrics.length === 0) return { nextLyric: null };
    const currentIndex = subCategoryLyrics.findIndex(l => l.id === lyric.id);
    return {
      nextLyric: currentIndex < subCategoryLyrics.length - 1 ? subCategoryLyrics[currentIndex + 1] : null
    };
  }, [lyric, subCategoryLyrics]);

  const cleanupAudio = () => {
    if (sourceNodeRef.current) {
      try { sourceNodeRef.current.stop(); } catch(e) {}
      sourceNodeRef.current = null;
    }
    if (staticAudioRef.current) {
      staticAudioRef.current.pause();
      staticAudioRef.current = null;
    }
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
    setIsPlaying(false);
    setProgress(0);
  };

  const onRecitationEnd = () => {
    cleanupAudio();
    if (nextLyric) {
      navigate(`/lyric/${nextLyric.id}`);
    }
  };

  const playGeminiTts = async (text: string) => {
    setIsBuffering(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: `Please recite this Urdu poetry clearly and emotionally:\n\n${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: 'Zephyr' },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data returned");

      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();

      const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);

      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = onRecitationEnd;

      playbackStartTimeRef.current = ctx.currentTime;
      source.start(0);
      sourceNodeRef.current = source;
      setIsPlaying(true);

      progressIntervalRef.current = window.setInterval(() => {
        const elapsed = ctx.currentTime - playbackStartTimeRef.current;
        setProgress((elapsed / audioBuffer.duration) * 100);
      }, 100);

    } catch (error) {
      console.error("TTS failed:", error);
    } finally {
      setIsBuffering(false);
    }
  };

  const toggleAudio = async () => {
    if (isPlaying) {
      cleanupAudio();
      return;
    }

    if (lyric?.audioUrl) {
      setIsBuffering(true);
      const audio = new Audio(lyric.audioUrl);
      staticAudioRef.current = audio;
      audio.oncanplay = () => {
        setIsBuffering(false);
        audio.play();
        setIsPlaying(true);
      };
      audio.onended = onRecitationEnd;
      audio.onerror = () => {
        setIsBuffering(false);
        playGeminiTts(lyric.content);
      };
    } else if (lyric?.content) {
      playGeminiTts(lyric.content);
    }
  };

  useEffect(() => {
    return () => cleanupAudio();
  }, [id]);

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;

  const rawLines = lyric.content.split('\n').map(l => l.trim()).filter(l => l !== '');

  return (
    <div 
      className="flex flex-col items-center w-full min-h-screen pb-32 pt-4 px-4 relative animate-nativeAppTransition overflow-x-hidden"
      style={{ backgroundColor: displaySettings.backgroundColor }}
    >
      {/* Recitation Toggle (Floating) */}
      <div className="fixed bottom-24 right-6 z-40 flex flex-col gap-3">
        {isPlaying && (
          <div className="bg-[#5D4037] text-white text-[10px] font-bold px-3 py-1 rounded-full text-center shadow-lg animate-pulse uppercase tracking-widest">
            Reciting...
          </div>
        )}
        <button 
          onClick={toggleAudio}
          className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all active:scale-90 ${isPlaying ? 'bg-red-700 text-white' : 'bg-[#5D4037] text-white'}`}
          disabled={isBuffering}
        >
          {isBuffering ? (
            <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
          ) : isPlaying ? (
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="12" height="16" rx="1"/></svg>
          ) : (
            <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>
          )}
