import { Category, SubCategory, Lyric, User, UserRole, DisplaySettings, GlobalSettings } from './types';
import { INITIAL_CATEGORIES, INITIAL_SUBCATEGORIES, INITIAL_LYRICS } from './constants';

const DB_KEYS = {
  CATEGORIES: 'islamic_v4_cats',
  SUBCATEGORIES: 'islamic_v4_subs',
  LYRICS: 'islamic_v4_lyrics',
  USERS: 'islamic_v4_users',
  SESSION: 'islamic_v4_session',
  DISPLAY_SETTINGS: 'islamic_v4_disp',
  GLOBAL_SETTINGS: 'islamic_v4_glob'
};

const DEFAULT_DISPLAY: DisplaySettings = {
  backgroundColor: '#F5F5DC',
  textColor: '#1A0F0D',
  fontSize: 24,
  lineHeight: 2.5
};

const DEFAULT_GLOBAL: GlobalSettings = {
  isSignupEnabled: true,
  isLoginEnabled: true
};

export const db = {
  // Global Admin Settings
  getGlobalSettings: (): GlobalSettings => {
    const data = localStorage.getItem(DB_KEYS.GLOBAL_SETTINGS);
    return data ? JSON.parse(data) : DEFAULT_GLOBAL;
  },
  saveGlobalSettings: (settings: GlobalSettings) => {
    localStorage.setItem(DB_KEYS.GLOBAL_SETTINGS, JSON.stringify(settings));
  },

  // Auth & Session
  getCurrentUser: (): User | null => {
    const session = localStorage.getItem(DB_KEYS.SESSION);
    return session ? JSON.parse(session) : null;
  },

  getAllUsers: (): User[] => {
    const data = localStorage.getItem(DB_KEYS.USERS);
    return data ? JSON.parse(data) : [];
  },

  register: (user: Partial<User>): User | string => {
    const users = db.getAllUsers();
    if (users.find(u => u.username === user.username)) return "صارف کا نام پہلے سے موجود ہے";

    const newUser: User = {
      id: Math.random().toString(36).substr(2, 9),
      username: user.username!,
      password: user.password!,
      name: user.name || '',
      email: user.email || '',
      phone: user.phone || '',
      role: users.length === 0 ? UserRole.ADMIN : UserRole.USER, // First user is Admin
      isEnabled: true,
      createdAt: Date.now(),
      ...user
    };

    users.push(newUser);
    localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));

    // Seed initial data for new user if they want
    db.seedUserData(newUser.id);

    return newUser;
  },

  updateUser: (userId: string, updates: Partial<User>) => {
    const users = db.getAllUsers();
    const idx = users.findIndex(u => u.id === userId);
    if (idx > -1) {
      users[idx] = { ...users[idx], ...updates };
      localStorage.setItem(DB_KEYS.USERS, JSON.stringify(users));
      // Update session if it's the same user
      const current = db.getCurrentUser();
      if (current?.id === userId) {
        localStorage.setItem(DB_KEYS.SESSION, JSON.stringify(users[idx]));
      }
    }
  },

  login: (username: string, password?: string): User | string => {
    const users = db.getAllUsers();
    const user = users.find(u => u.username === username && u.password === password);
    if (!user) return "غلط نام یا پاس ورڈ";
    if (!user.isEnabled) return "آپ کا اکاؤنٹ معطل ہے";

    localStorage.setItem(DB_KEYS.SESSION, JSON.stringify(user));
    return user;
  },

  logout: () => localStorage.removeItem(DB_KEYS.SESSION),

  // User-Specific Content Seeding
  seedUserData: (userId: string) => {
    const cats: Category[] = INITIAL_CATEGORIES.map(c => ({ ...c, userId }));
    const subs: SubCategory[] = INITIAL_SUBCATEGORIES.map(s => ({ ...s, userId }));
    const lyrics: Lyric[] = INITIAL_LYRICS.map(l => ({ ...l, userId }));

    const existingCats = db.getCategories(userId);
    if (existingCats.length === 0) {
      localStorage.setItem(DB_KEYS.CATEGORIES, JSON.stringify([...db.getCategories(), ...cats]));
      localStorage.setItem(DB_KEYS.SUBCATEGORIES, JSON.stringify([...db.getSubCategories(), ...subs]));
      localStorage.setItem(DB_KEYS.LYRICS, JSON.stringify([...db.getLyrics(), ...lyrics]));
    }
  },

  // Content Handlers (Filtered by current user)
  getCategories: (userId?: string): Category[] => {
    const data = localStorage.getItem(DB_KEYS.CATEGORIES);
    const all: Category[] = data ? JSON.parse(data) : [];
    return userId ? all.filter(c => c.userId === userId) : all;
  },

  saveCategory: (userId: string, category: Category) => {
    const all = db.getCategories();
    const index = all.findIndex(c => c.id === category.id && c.userId === userId);
    if (index > -1) all[index] = category; else all.push({ ...category, userId });
    localStorage.setItem(DB_KEYS.CATEGORIES, JSON.stringify(all));
  },

  getSubCategories: (userId: string, categoryId?: string): SubCategory[] => {
    const data = localStorage.getItem(DB_KEYS.SUBCATEGORIES);
    let all: SubCategory[] = data ? JSON.parse(data) : [];
    let filtered = all.filter(s => s.userId === userId);
    if (categoryId) filtered = filtered.filter(s => s.categoryId === categoryId);
    return filtered.sort((a, b) => a.serial - b.serial);
  },

  getLyrics: (userId: string, subCategoryId?: string): Lyric[] => {
    const data = localStorage.getItem(DB_KEYS.LYRICS);
    let all: Lyric[] = data ? JSON.parse(data) : [];
    let filtered = all.filter(l => l.userId === userId);
    if (subCategoryId) filtered = filtered.filter(l => l.subCategoryId === subCategoryId);
    return filtered.sort((a, b) => a.serial - b.serial);
  },

  saveLyric: (userId: string, lyric: Lyric) => {
    const data = localStorage.getItem(DB_KEYS.LYRICS);
    const all: Lyric[] = data ? JSON.parse(data) : [];
    const index = all.findIndex(l => l.id === lyric.id && l.userId === userId);
    if (index > -1) all[index] = lyric; else all.push({ ...lyric, userId });
    localStorage.setItem(DB_KEYS.LYRICS, JSON.stringify(all));
  },

  getSettings: (): DisplaySettings => {
    const data = localStorage.getItem(DB_KEYS.DISPLAY_SETTINGS);
    return data ? JSON.parse(data) : DEFAULT_DISPLAY;
  },

  saveSettings: (settings: DisplaySettings) => {
    localStorage.setItem(DB_KEYS.DISPLAY_SETTINGS, JSON.stringify(settings));
  }
};

import React, { useState } from 'react';
import { db } from '../db';
import { UserRole } from '../types';

export const Auth: React.FC<{ onAuth: () => void }> = ({ onAuth }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [formData, setFormData] = useState({ username: '', password: '', name: '', email: '', phone: '' });
  const [error, setError] = useState('');
  const globals = db.getGlobalSettings();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (isLogin) {
      if (!globals.isLoginEnabled) {
        setError("لاگ ان فی الحال بند ہے");
        return;
      }
      const res = db.login(formData.username, formData.password);
      if (typeof res === 'string') setError(res);
      else onAuth();
    } else {
      if (!globals.isSignupEnabled) {
        setError("رجسٹریشن فی الحال بند ہے");
        return;
      }
      const res = db.register(formData);
      if (typeof res === 'string') setError(res);
      else onAuth();
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-6 animate-nativeAppTransition">
      <div className="w-full max-w-sm bg-white p-8 rounded-2xl shadow-xl border border-[#5D4037]/5">
        <h2 className="text-3xl font-bold urdu-text text-center mb-8" style={{ color: '#5D4037' }}>
          {isLogin ? "لاگ ان کریں" : "نیا اکاؤنٹ بنائیں"}
        </h2>

        {error && <div className="mb-4 p-3 bg-red-50 text-red-600 urdu-text text-center text-sm rounded-lg">{error}</div>}

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <>
              <input 
                placeholder="آپ کا نام" 
                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right urdu-text focus:border-[#5D4037] outline-none"
                value={formData.name}
                onChange={e => setFormData({...formData, name: e.target.value})}
                required
              />
              <input 
                placeholder="ای میل" 
                type="email"
                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right urdu-text focus:border-[#5D4037] outline-none"
                value={formData.email}
                onChange={e => setFormData({...formData, email: e.target.value})}
              />
              <input 
                placeholder="فون نمبر" 
                className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right urdu-text focus:border-[#5D4037] outline-none"
                value={formData.phone}
                onChange={e => setFormData({...formData, phone: e.target.value})}
              />
            </>
          )}
          <input 
            placeholder="یوزر نیم" 
            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right urdu-text focus:border-[#5D4037] outline-none"
            value={formData.username}
            onChange={e => setFormData({...formData, username: e.target.value})}
            required
          />
          <input 
            placeholder="پاس ورڈ" 
            type="password"
            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right urdu-text focus:border-[#5D4037] outline-none"
            value={formData.password}
            onChange={e => setFormData({...formData, password: e.target.value})}
            required
          />

          <button type="submit" className="w-full py-4 bg-[#5D4037] text-white rounded-full urdu-text text-xl font-bold shadow-lg active:scale-95 transition-all">
            {isLogin ? "داخل ہوں" : "رجسٹر کریں"}
          </button>
        </form>

        <button 
          onClick={() => setIsLogin(!isLogin)} 
          className="w-full mt-6 text-[#5D4037]/60 urdu-text text-sm hover:text-[#5D4037]"
        >
          {isLogin ? "نیا اکاؤنٹ بنائیں؟" : "پہلے سے اکاؤنٹ موجود ہے؟"}
        </button>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { HashRouter as Router, Routes, Route, useLocation, Navigate } from 'react-router-dom';
import { Layout } from './components/Layout';
import { Home } from './components/Home';
import { Cover } from './components/Cover';
import { CategoryDetail } from './components/CategoryDetail';
import { SubCategoryDetail } from './components/SubCategoryDetail';
import { LyricView } from './components/LyricView';
import { Admin } from './components/Admin';
import { Settings } from './components/Settings';
import { Auth } from './components/Auth';
import { db } from './db';

const ScrollToTop = () => {
  const { pathname } = useLocation();
  useEffect(() => { window.scrollTo(0, 0); }, [pathname]);
  return null;
};

const App: React.FC = () => {
  const [user, setUser] = useState(db.getCurrentUser());

  const handleAuth = () => setUser(db.getCurrentUser());

  return (
    <Router>
      <ScrollToTop />
      <Layout>
        {!user ? (
          <Auth onAuth={handleAuth} />
        ) : (
          <Routes>
            <Route path="/" element={<Cover />} />
            <Route path="/categories" element={<Home />} />
            <Route path="/category/:id" element={<CategoryDetail />} />
            <Route path="/subcategory/:id" element={<SubCategoryDetail />} />
            <Route path="/lyric/:id" element={<LyricView />} />
            <Route path="/admin" element={<Admin />} />
            <Route path="/settings" element={<Settings onLogout={() => setUser(null)} />} />
            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        )}
      </Layout>
    </Router>
  );
};

export default App;

import React, { useState } from 'react';
import { db } from '../db';
import { DisplaySettings, User } from '../types';

export const Settings: React.FC<{ onLogout: () => void }> = ({ onLogout }) => {
  const [settings, setSettings] = useState<DisplaySettings>(db.getSettings());
  const [user, setUser] = useState<User>(db.getCurrentUser()!);
  const [profileMsg, setProfileMsg] = useState('');

  const updateSetting = (key: keyof DisplaySettings, value: any) => {
    const newSettings = { ...settings, [key]: value };
    setSettings(newSettings);
    db.saveSettings(newSettings);
  };

  const handleUpdateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    db.updateUser(user.id, user);
    setProfileMsg("پروفائل اپ ڈیٹ ہو گئی");
    setTimeout(() => setProfileMsg(''), 3000);
  };

  return (
    <div className="flex flex-col w-full h-full p-6 animate-fadeIn urdu-text space-y-10 pb-20">
      <h2 className="text-3xl font-bold text-center" style={{ color: '#5D4037' }}>ترتیبات و پروفائل</h2>

      {/* Profile Section */}
      <section className="bg-white p-6 rounded-2xl shadow-sm border border-[#5D4037]/5 space-y-4">
        <h3 className="text-lg font-bold opacity-40 uppercase tracking-widest text-right">آپ کی معلومات</h3>
        {profileMsg && <div className="p-2 bg-green-50 text-green-600 text-center text-xs rounded-lg">{profileMsg}</div>}
        <form onSubmit={handleUpdateProfile} className="space-y-4">
          <input 
            value={user.name} 
            onChange={e => setUser({...user, name: e.target.value})}
            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right" 
            placeholder="نام"
          />
          <input 
            value={user.email} 
            onChange={e => setUser({...user, email: e.target.value})}
            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right" 
            placeholder="ای میل"
          />
          <input 
            value={user.phone} 
            onChange={e => setUser({...user, phone: e.target.value})}
            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right" 
            placeholder="فون نمبر"
          />
          <input 
            type="password"
            value={user.password} 
            onChange={e => setUser({...user, password: e.target.value})}
            className="w-full p-3 bg-gray-50 border border-gray-100 rounded-lg text-right" 
            placeholder="نیا پاس ورڈ"
          />
          <button type="submit" className="w-full py-3 bg-[#5D4037] text-white rounded-xl text-sm font-bold">محفوظ کریں</button>
        </form>
      </section>

      {/* Visual Settings Section */}
      <section className="space-y-6">
        <div>
          <div className="flex justify-between items-center mb-2">
            <h3 className="text-sm font-bold opacity-40 uppercase tracking-widest">تحریر کا سائز</h3>
            <span className="text-xs font-bold font-sans">{settings.fontSize}px</span>
          </div>
          <input
            type="range"
            min="16"
            max="40"
            value={settings.fontSize}
            onChange={(e) => updateSetting('fontSize', parseInt(e.target.value))}
            className="w-full h-1.5 bg-[#5D4037]/10 rounded-lg appearance-none cursor-pointer accent-[#5D4037]"
          />
        </div>

        <div>
          <div className="flex justify-between items-center mb-2">
            <h3 className="text-sm font-bold opacity-40 uppercase tracking-widest">سطروں کا فاصلہ</h3>
            <span className="text-xs font-bold font-sans">{settings.lineHeight.toFixed(1)}</span>
          </div>
          <input
            type="range"
            min="1.5"
            max="3.5"
            step="0.1"
            value={settings.lineHeight}
            onChange={(e) => updateSetting('lineHeight', parseFloat(e.target.value))}
            className="w-full h-1.5 bg-[#5D4037]/10 rounded-lg appearance-none cursor-pointer accent-[#5D4037]"
          />
        </div>
      </section>

      <div className="pt-4 space-y-3">
        <button 
          onClick={() => { db.logout(); onLogout(); }}
          className="w-full py-4 bg-red-700 text-white rounded-2xl font-bold shadow-lg shadow-red-700/20"
        >
          لاگ آؤٹ کریں
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { User, UserRole, GlobalSettings } from '../types';

export const Admin: React.FC = () => {
  const currentUser = db.getCurrentUser();
  const [users, setUsers] = useState<User[]>(db.getAllUsers());
  const [globals, setGlobals] = useState<GlobalSettings>(db.getGlobalSettings());

  if (currentUser?.role !== UserRole.ADMIN) {
    return <div className="p-10 text-center urdu-text">آپ کے پاس ایڈمن کے اختیارات نہیں ہیں۔</div>;
  }

  const toggleGlobal = (key: keyof GlobalSettings) => {
    const next = { ...globals, [key]: !globals[key] };
    setGlobals(next);
    db.saveGlobalSettings(next);
  };

  const toggleUser = (userId: string) => {
    const u = users.find(x => x.id === userId);
    if (u) {
      db.updateUser(userId, { isEnabled: !u.isEnabled });
      setUsers(db.getAllUsers());
    }
  };

  return (
    <div className="p-6 urdu-text space-y-8 animate-fadeIn pb-24 overflow-y-auto">
      <h2 className="text-3xl font-bold text-[#5D4037] text-center mb-6">ایڈمن کنٹرولز</h2>

      {/* Global Flags */}
      <section className="bg-white p-6 rounded-2xl shadow-sm border border-[#5D4037]/5 space-y-4">
        <h3 className="text-lg font-bold opacity-40 uppercase">سسٹم سیٹنگز</h3>
        <div className="flex items-center justify-between p-3 border border-gray-100 rounded-xl">
          <button onClick={() => toggleGlobal('isSignupEnabled')} className={`px-4 py-1 rounded-full text-xs font-bold ${globals.isSignupEnabled ? 'bg-green-600' : 'bg-red-600'} text-white`}>
            {globals.isSignupEnabled ? 'آن ہے' : 'آف ہے'}
          </button>
          <span className="font-medium text-right flex-1 pr-4">سائن اپ (رجسٹریشن)</span>
        </div>
        <div className="flex items-center justify-between p-3 border border-gray-100 rounded-xl">
          <button onClick={() => toggleGlobal('isLoginEnabled')} className={`px-4 py-1 rounded-full text-xs font-bold ${globals.isLoginEnabled ? 'bg-green-600' : 'bg-red-600'} text-white`}>
            {globals.isLoginEnabled ? 'آن ہے' : 'آف ہے'}
          </button>
          <span className="font-medium text-right flex-1 pr-4">لاگ ان</span>
        </div>
      </section>

      {/* User Management */}
      <section className="space-y-4">
        <h3 className="text-lg font-bold opacity-40 uppercase text-right">صارفین کی فہرست ({users.length})</h3>
        <div className="space-y-3">
          {users.map(u => (
            <div key={u.id} className="bg-white p-4 rounded-xl border border-[#5D4037]/5 flex items-center justify-between gap-4">
              <div className="flex gap-2">
                 <button 
                  onClick={() => toggleUser(u.id)}
                  disabled={u.id === currentUser.id}
                  className={`text-[10px] px-3 py-1 rounded-lg font-bold border ${u.isEnabled ? 'text-red-600 border-red-100 bg-red-50' : 'text-green-600 border-green-100 bg-green-50'} disabled:opacity-20`}
                 >
                   {u.isEnabled ? "معطل کریں" : "بحال کریں"}
                 </button>
              </div>
              <div className="text-right flex-1 overflow-hidden">
                <div className="font-bold truncate text-[#5D4037]">{u.name || u.username}</div>
                <div className="text-[10px] opacity-40 font-mono">@{u.username} • {u.role}</div>
                <div className="text-[9px] opacity-30 truncate">{u.email}</div>
              </div>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { Link } from 'react-router-dom';
import { db } from '../db';
import { Category, Lyric, DisplaySettings } from '../types';

export const Home: React.FC = () => {
  const user = db.getCurrentUser();
  const [categories, setCategories] = useState<Category[]>(() => db.getCategories(user?.id));
  const [allLyrics, setAllLyrics] = useState<Lyric[]>(() => db.getLyrics(user?.id!));
  const [searchQuery, setSearchQuery] = useState('');
  const settings = db.getSettings();

  useEffect(() => {
    if (user) {
      setCategories(db.getCategories(user.id));
      setAllLyrics(db.getLyrics(user.id));
    }
  }, [user]);

  const filteredLyrics = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase();
    return allLyrics.filter(lyric => 
      lyric.title.toLowerCase().includes(query) || 
      lyric.content.toLowerCase().includes(query)
    );
  }, [searchQuery, allLyrics]);

  return (
    <div className="flex flex-col w-full min-h-screen" style={{ backgroundColor: settings.backgroundColor }}>
      <div className="p-4 border-b border-black/5">
        <input
          placeholder="کلام تلاش کریں..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full p-3 bg-white/50 border border-[#5D4037]/20 rounded-xl text-right urdu-text"
          dir="rtl"
        />
      </div>

      <div className="divide-y divide-black/5 pb-20">
        {searchQuery.trim() ? (
          filteredLyrics.map(lyric => (
            <Link key={lyric.id} to={`/lyric/${lyric.id}`} className="flex justify-end p-5 active:bg-black/5">
              <span className="text-xl urdu-text text-right">{lyric.title}</span>
            </Link>
          ))
        ) : (
          categories.map(cat => (
            <Link key={cat.id} to={`/category/${cat.id}`} className="flex items-center justify-between p-6 active:bg-black/5 group">
              <svg className="opacity-10 group-active:opacity-100" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="3"><path d="m15 18-6-6 6-6"/></svg>
              <div className="flex items-center gap-4">
                <span className="text-2xl urdu-text font-medium">{cat.name}</span>
                <div className="w-8 h-8 rounded-full bg-black/5 flex items-center justify-center text-xs font-bold text-[#5D4037]/60">
                  {cat.serial}
                </div>
              </div>
            </Link>
          ))
        )}
      </div>
    </div>
  );
};

