export const Home: React.FC = () => {
  const user = db.getCurrentUser();
  const [categories, setCategories] = useState<Category[]>([]);
  const [allLyrics, setAllLyrics] = useState<Lyric[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    if (user) {
      const fetchData = async () => {
        try {
          const [cats, lyrics] = await Promise.all([
            db.getCategories(user.id),
            db.getLyrics(user.id)
          ]);
          setCategories(cats);
          setAllLyrics(lyrics);
        } catch (e) {
          console.error(e);
        } finally {
          setLoading(false);
        }
      };
      fetchData();
    }
  }, [user]);

  const filteredLyrics = useMemo(() => {
    if (!searchQuery.trim()) return [];
    const query = searchQuery.toLowerCase();
    return allLyrics.filter(lyric => 
      lyric.title.toLowerCase().includes(query) || 
      lyric.content.toLowerCase().includes(query)
    );
  }, [searchQuery, allLyrics]);

  if (loading) {
    return <div className="flex justify-center p-20"><div className="loading-spinner"></div></div>;
  }

  return (
    <div className="flex flex-col w-full min-h-screen">
      <div className="p-4 border-b border-black/5">
        <input
          placeholder="کلام تلاش کریں..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full p-3 bg-white/50 border border-[#5D4037]/20 rounded-xl text-right urdu-text outline-none"
          dir="rtl"
        />
      </div>

      <div className="divide-y divide-black/5 pb-20 page-transition">
        {searchQuery.trim() ? (
          filteredLyrics.map(lyric => (
            <Link key={lyric.id} to={`/lyric/${lyric.id}`} className="flex justify-end p-5 active:bg-black/5">
              <span className="text-xl urdu-text text-right">{lyric.title}</span>
            </Link>
          ))
