import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../db';
import { Lyric, DisplaySettings } from '../types';
import { GoogleGenAI, Modality } from "@google/genai";

function decode(base64: string) {
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

async function decodeAudioData(
  data: Uint8Array,
  ctx: AudioContext,
  sampleRate: number,
  numChannels: number,
): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

export const LyricView: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const user = db.getCurrentUser();
  const [lyric, setLyric] = useState<Lyric | null>(null);
  const [displaySettings, setDisplaySettings] = useState<DisplaySettings>({
    backgroundColor: '#F5F5DC',
    textColor: '#1A0F0D',
    fontSize: 24,
    lineHeight: 2.5
  });

  const [isPlaying, setIsPlaying] = useState(false);
  const [isBuffering, setIsBuffering] = useState(false);
  const [progress, setProgress] = useState(0);
  const [isFavorite, setIsFavorite] = useState(false);
  const [interpretation, setInterpretation] = useState<string | null>(null);
  const [explaining, setExplaining] = useState(false);

  const audioContextRef = useRef<AudioContext | null>(null);
  const sourceNodeRef = useRef<AudioBufferSourceNode | null>(null);
  const staticAudioRef = useRef<HTMLAudioElement | null>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const playbackStartTimeRef = useRef<number>(0);

  useEffect(() => {
    if (id && user) {
      const fetchData = async () => {
        const [allLyrics, settings, favs] = await Promise.all([
          db.getLyrics(user.id),
          db.getSettings(user.id),
          db.getFavorites(user.id)
        ]);
        const currentLyric = allLyrics.find(l => l.id === id);
        if (currentLyric) {
          setLyric(currentLyric);
          setIsFavorite(favs.includes(currentLyric.id));
        }
        setDisplaySettings(settings);
      };
      fetchData();
    }
    setInterpretation(null);
  }, [id]);

  const toggleFav = async () => {
    if (!user || !lyric) return;
    const newState = await db.toggleFavorite(user.id, lyric.id);
    setIsFavorite(newState);
  };

  const shareLyric = async () => {
    if (!lyric) return;
    const text = `*${lyric.title}*\n\n${lyric.content}\n\n_کلامِ رضا لائبریری سے بھیجا گیا_`;
    if (navigator.share) {
      try {
        await navigator.share({ title: lyric.title, text: text });
      } catch (err) { console.error(err); }
    } else {
      // Fallback for browsers that don't support Web Share API
      navigator.clipboard.writeText(text);
      alert("کلام کاپی کر لیا گیا ہے!");
    }
  };

  const getInterpretation = async () => {
    if (!lyric) return;
    setExplaining(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `You are an Islamic scholar. Explain the following poetry in beautiful simple Urdu. \n\n${lyric.content}`,
      });
      setInterpretation(response.text);
    } catch (err) {
      setInterpretation("معذرت، تشریح دستیاب نہیں ہو سکی۔");
    } finally {
      setExplaining(false);
    }
  };

  const cleanupAudio = () => {
    if (sourceNodeRef.current) { try { sourceNodeRef.current.stop(); } catch(e) {} sourceNodeRef.current = null; }
    if (staticAudioRef.current) { staticAudioRef.current.pause(); staticAudioRef.current = null; }
    if (progressIntervalRef.current) { window.clearInterval(progressIntervalRef.current); progressIntervalRef.current = null; }
    setIsPlaying(false);
    setProgress(0);
  };

  const playGeminiTts = async (text: string) => {
    setIsBuffering(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-preview-tts',
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio");
      if (!audioContextRef.current) audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const ctx = audioContextRef.current;
      if (ctx.state === 'suspended') await ctx.resume();
      const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(ctx.destination);
      source.onended = cleanupAudio;
      playbackStartTimeRef.current = ctx.currentTime;
      source.start(0);
      sourceNodeRef.current = source;
      setIsPlaying(true);
      progressIntervalRef.current = window.setInterval(() => {
        const elapsed = ctx.currentTime - playbackStartTimeRef.current;
        setProgress((elapsed / audioBuffer.duration) * 100);
      }, 100);
    } catch (error) { console.error(error); } finally { setIsBuffering(false); }
  };

  const toggleAudio = async () => {
    if (isPlaying) { cleanupAudio(); return; }
    if (lyric?.audioUrl) {
      setIsBuffering(true);
      const audio = new Audio(lyric.audioUrl);
      staticAudioRef.current = audio;
      audio.onplay = () => { setIsBuffering(false); setIsPlaying(true); };
      audio.onended = cleanupAudio;
      audio.play();
    } else if (lyric?.content) {
      playGeminiTts(lyric.content);
    }
  };

  useEffect(() => { return () => cleanupAudio(); }, [id]);

  if (!lyric) return <div className="text-center p-10 urdu-text">کلام نہیں ملا</div>;
  const rawLines = lyric.content.split('\n').map(l => l.trim()).filter(l => l !== '');

  return (
    <div className="flex flex-col items-center w-full min-h-screen pb-32 pt-4 px-4 relative page-transition" style={{ backgroundColor: displaySettings.backgroundColor }}>

      {/* Floating Action Menu */}
      <div className="fixed bottom-24 right-6 z-40 flex flex-col gap-3 items-end">
        <button onClick={shareLyric} className="w-12 h-12 rounded-full shadow-lg flex items-center justify-center bg-white border border-[#5D4037]/20 text-[#5D4037] transition-all active:scale-90">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
        </button>

        <button onClick={toggleFav} className="w-12 h-12 rounded-full shadow-lg flex items-center justify-center bg-white border border-[#5D4037]/20 text-red-600 transition-all active:scale-90">
          <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill={isFavorite ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2"><path d="M19 14c1.49-1.46 3-3.21 3-5.5A5.5 5.5 0 0 0 16.5 3c-1.76 0-3 .5-4.5 2-1.5-1.5-2.74-2-4.5-2A5.5 5.5 0 0 0 2 8.5c0 2.3 1.5 4.05 3 5.5l7 7Z"/></svg>
        </button>

        <button onClick={getInterpretation} disabled={explaining} className="w-12 h-12 rounded-full shadow-lg flex items-center justify-center bg-white border border-[#5D4037]/20 text-[#2E7D32] transition-all active:scale-90">
          {explaining ? <div className="loading-spinner !w-4 !h-4"></div> : <span className="text-xs font-bold urdu-text">تشریح</span>}
        </button>

        <button onClick={toggleAudio} className={`w-14 h-14 rounded-full shadow-2xl flex items-center justify-center transition-all active:scale-90 ${isPlaying ? 'bg-red-700 text-white' : 'bg-[#5D4037] text-white'}`} disabled={isBuffering}>
          {isBuffering ? <div className="loading-spinner !w-5 !h-5 !border-white/30 !border-t-white"></div> : isPlaying ? <svg width="24" height="24" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="12" height="16" rx="1"/></svg> : <svg width="28" height="28" viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg>}
        </button>
      </div>

      <div className="w-full max-w-lg mx-auto">
        <h2 className="urdu-text text-3xl md:text-4xl font-bold text-center mb-10 mt-6" style={{ color: displaySettings.textColor }}>{lyric.title}</h2>

        {interpretation && (
          <div className="mb-10 p-6 bg-white/60 rounded-3xl border border-[#2E7D32]/20 animate-fadeIn text-right relative">
            <p className="urdu-text text-lg leading-relaxed text-[#1A4D1F]">{interpretation}</p>
            <button onClick={() => setInterpretation(null)} className="mt-4 text-xs opacity-40 urdu-text">بند کریں</button>
          </div>
        )}

        {Array.from({ length: Math.ceil(rawLines.length / 2) }).map((_, i) => (
          <React.Fragment key={i}>
            <div className="flex flex-col items-center w-full py-8">
              <p className="urdu-text text-2xl md:text-3xl text-center leading-[2.5] px-2 w-full break-words font-medium" style={{ color: displaySettings.textColor }}>{rawLines[i * 2]}</p>
              {rawLines[i * 2 + 1] && <p className="urdu-text text-2xl md:text-3xl text-center leading-[2.5] px-2 w-full break-words font-medium" style={{ color: displaySettings.textColor }}>{rawLines[i * 2 + 1]}</p>}
            </div>
            {i < Math.ceil(rawLines.length / 2) - 1 && <div className="w-24 border-b-2 border-[#5D4037]/10 mx-auto"></div>}
          </React.Fragment>
        ))}
      </div>

      {isPlaying && <div className="fixed bottom-16 left-0 right-0 h-1 bg-black/5 z-50"><div className="h-full bg-red-700 transition-all duration-300" style={{ width: `${progress}%` }} /></div>}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { db } from '../db';
import { Category, SubCategory, DisplaySettings } from '../types';

export const CategoryDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const [category, setCategory] = useState<Category | null>(null);
  const [subCategories, setSubCategories] = useState<SubCategory[]>([]);
  const [newSubName, setNewSubName] = useState('');
  const [settings, setSettings] = useState<DisplaySettings>({
    backgroundColor: '#F5F5DC',
    textColor: '#1A0F0D',
    fontSize: 24,
    lineHeight: 2.5
  });

  const loadData = async () => {
    const user = db.getCurrentUser();
    if (id && user) {
      const [allCats, subs, s] = await Promise.all([
        db.getCategories(user.id),
        db.getSubCategories(user.id, id),
        db.getSettings(user.id)
      ]);
      setCategory(allCats.find(c => c.id === id) || null);
      setSubCategories(subs);
      setSettings(s);
    }
  };

  useEffect(() => { loadData(); }, [id]);

  const handleAddSub = async () => {
    const user = db.getCurrentUser();
    if (!user || !id || !newSubName.trim()) return;
    await db.addSubCategory(user.id, id, newSubName);
    setNewSubName('');
    loadData();
  };

  if (!category) return <div className="text-center p-10 urdu-text">عنوان نہیں ملا</div>;

  return (
    <div className="flex flex-col w-full min-h-screen" style={{ backgroundColor: settings.backgroundColor }}>
      {/* Add New Subcategory Input */}
      <div className="p-4 bg-white/40 border-b border-black/5 flex gap-2">
         <button 
           onClick={handleAddSub}
           className="bg-[#5D4037] text-white px-5 rounded-xl text-sm font-bold urdu-text pt-1"
         >
           شامل کریں
         </button>
         <input 
           value={newSubName}
           onChange={e => setNewSubName(e.target.value)}
           placeholder="نیا ذیلی عنوان..."
           className="flex-1 p-3 bg-white/70 border border-[#5D4037]/10 rounded-xl text-right urdu-text outline-none"
           dir="rtl"
         />
      </div>

      <div className="divide-y divide-black/5 p-2">
        {subCategories.length > 0 ? (
          subCategories.map((sub) => (
            <Link
              key={sub.id}
              to={`/subcategory/${sub.id}`}
              className="flex items-center justify-between p-5 active:bg-black/5 transition-colors group"
            >
              <svg className="opacity-10" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#5D4037" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
              <div className="flex items-center gap-4">
                <span className="text-2xl urdu-text font-medium" style={{ color: settings.textColor }}>{sub.name}</span>
                <div className="w-8 h-8 rounded-full bg-black/5 flex items-center justify-center text-xs font-bold text-[#5D4037]/60">
                  {sub.serial}
                </div>
              </div>
            </Link>
          ))
        ) : (
          <div className="text-center py-20 opacity-30 urdu-text italic">کوئی ذیلی عنوان موجود نہیں ہے</div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { db } from '../db';
import { DisplaySettings } from '../types';

const Header: React.FC<{ title?: string }> = ({ title }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const isCover = location.pathname === '/';
  const [isOnline, setIsOnline] = React.useState(navigator.onLine);

  React.useEffect(() => {
    const handleStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', handleStatus);
    window.addEventListener('offline', handleStatus);
    return () => {
      window.removeEventListener('online', handleStatus);
      window.removeEventListener('offline', handleStatus);
    };
  }, []);

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-[#5D4037] text-white shadow-md flex items-center justify-between px-3 h-14 border-b border-white/5">
      <div className="flex items-center gap-2 overflow-hidden flex-1">
        {!isCover && (
          <button onClick={() => navigate(-1)} className="p-1 active:bg-white/10 rounded-full shrink-0 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="12" x2="5" y2="12"/><polyline points="12 19 5 12 12 5"/></svg>
          </button>
        )}
        <h1 className="text-xl urdu-text truncate font-medium pt-1 pr-2 flex-1 text-center">
          {title || "کلامِ رضا"}
        </h1>
        <div className="flex items-center gap-2 px-2">
          <div className={`w-2 h-2 rounded-full transition-all duration-500 ${isOnline ? 'bg-green-400 shadow-[0_0_8px_rgba(74,222,128,0.6)]' : 'bg-red-500 shadow-[0_0_8px_rgba(239,68,68,0.6)]'}`} title={isOnline ? "کلاؤڈ سے منسلک ہے" : "آف لائن"}></div>
        </div>
      </div>
    </header>
  );
};

